namespace Tihloh\Prefab; use BadMethodCallException; use RuntimeException;
if(!class_exists(PrefabConfig::class,false)){final class PrefabConfig{private static array $common=[],$modules=[];public static function set(array $c):void{$m=$c['modules']??[];unset($c['modules']);self::$common=array_replace_recursive(self::$common,$c);if(is_array($m))self::$modules=array_replace_recursive(self::$modules,$m);}public static function get(string $k,mixed $d=null):mixed{return array_key_exists($k,self::$common)?self::$common[$k]:$d;}public static function module(string $m,string $k,mixed $d=null):mixed{return self::resolve($m,$k,default:$d)['value'];}public static function resolve(string $m,string $k,array $l=[],mixed $d=null):array{if(array_key_exists($k,$l))return['value'=>$l[$k],'source'=>'module-local'];if(isset(self::$modules[$m])&&array_key_exists($k,self::$modules[$m]))return['value'=>self::$modules[$m][$k],'source'=>'prefab-config-module'];if(array_key_exists($k,self::$common))return['value'=>self::$common[$k],'source'=>'prefab-config-common'];return['value'=>$d,'source'=>'internal-default'];}public static function moduleConfig(string $m):array{return array_replace_recursive(self::$common,self::$modules[$m]??[]);}public static function moduleOnly(string $m):array{return self::$modules[$m]??[];}public static function reset():void{self::$common=[];self::$modules=[];}}}
if(!class_exists(PrefabRuntime::class,false)){final class PrefabRuntime{private static array $modules=[],$capabilities=[],$extensions=[],$resolutions=[];private static bool $configuring=false,$ready=false;public static function register(string $n,object $m):void{if(self::$ready&&!isset(self::$modules[$n]))throw new RuntimeException("Prefab runtime is ready; module '{$n}' cannot be registered afterward.");self::$modules[$n]=$m;self::configureAll();}public static function get(string $n):?object{return self::$modules[$n]??null;}public static function provide(string $c,mixed $v,string $p,int $priority=0,array $meta=[]):void{if($v===null){unset(self::$capabilities[$c][$p]);return;}self::$capabilities[$c][$p]=['value'=>$v,'provider'=>$p,'priority'=>$priority,'meta'=>$meta];}public static function resolveEntry(string $c,?string $p=null):?array{$x=self::$capabilities[$c]??[];if($p!==null)return$x[$p]??null;if(!$x)return null;uasort($x,fn($a,$b)=>$b['priority']<=>$a['priority']);$top=reset($x);$ties=array_filter($x,fn($e)=>$e['priority']===$top['priority']);if(count($ties)>1)throw new RuntimeException("Ambiguous Prefab capability '{$c}'.");return$top;}public static function resolve(string $c,?string $p=null):mixed{return self::resolveEntry($c,$p)['value']??null;}public static function extend(string $t,string $m,callable $h,string $p,int $priority=0,array $meta=[]):void{self::$extensions[$t][$m][$p]=['handler'=>$h,'provider'=>$p,'priority'=>$priority,'meta'=>$meta];}public static function hasExtension(object|string $t,string $m):bool{return self::extensionEntry($t,$m)!==null;}public static function extensionEntry(object|string $t,string $m):?array{$c=is_object($t)?$t::class:$t;$x=[];foreach(self::$extensions as$type=>$ms){if($c!==$type&&!is_a($c,$type,true))continue;foreach(($ms[$m]??[])as$p=>$e)$x[$type.':'.$p]=$e;}if(!$x)return null;uasort($x,fn($a,$b)=>$b['priority']<=>$a['priority']);$top=reset($x);$ties=array_filter($x,fn($e)=>$e['priority']===$top['priority']);if(count($ties)>1)throw new RuntimeException("Ambiguous Prefab fluent extension '{$m}' for '{$c}'.");return$top;}public static function callExtension(object $t,string $m,array $a=[]):mixed{$e=self::extensionEntry($t,$m);if(!$e){$c=$t::class;throw new BadMethodCallException("Prefab fluent extension '{$m}' is unavailable for {$c}.");}return($e['handler'])($t,...$a);}public static function extensionMethods(object|string $t):array{$c=is_object($t)?$t::class:$t;$r=[];foreach(self::$extensions as$type=>$ms)if($c===$type||is_a($c,$type,true))foreach(array_keys($ms)as$m)if(self::hasExtension($c,$m))$r[]=$m;return array_values(array_unique($r));}public static function recordResolution(string $m,string $r,string $s,array $d=[]):void{self::$resolutions[$m][$r]=['source'=>$s,...$d];}public static function explain(string $m):array{return self::$resolutions[$m]??[];}public static function inspect():array{return['ready'=>self::$ready,'modules'=>array_map(fn($m)=>$m::class,self::$modules),'capabilities'=>array_keys(self::$capabilities),'extensions'=>array_keys(self::$extensions),'resolutions'=>self::$resolutions];}public static function configureAll():void{if(self::$configuring)return;self::$configuring=true;try{foreach(self::$modules as$m)if(method_exists($m,'prefabConfigure'))$m->prefabConfigure();}finally{self::$configuring=false;}}public static function ready():void{self::configureAll();self::$ready=true;}public static function isReady():bool{return self::$ready;}public static function emitLog(array $e):void{$l=self::resolve('logger');if($l&&method_exists($l,'record'))$l->record($e);}public static function actorId():int|string|null{$a=self::resolve('actor_provider');return($a&&method_exists($a,'id'))?$a->id():null;}public static function reset():void{self::$modules=self::$capabilities=self::$extensions=self::$resolutions=[];self::$configuring=self::$ready=false;}}}
if(!trait_exists(FluentExtensions::class,false)){trait FluentExtensions{public function __call(string $m,array $a):mixed{return PrefabRuntime::callExtension($this,$m,$a);}public function hasExtension(string $m):bool{return PrefabRuntime::hasExtension($this,$m);}public function extensions():array{return PrefabRuntime::extensionMethods($this);}}}
